namespace sv_a01ee9c89bf24e01956feae10293996b.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_a01ee9c89bf24e01956feae10293996b.Services

<div class="channel-list">
    <h3 class="channel-list-header">Channels</h3>
    @foreach (var channel in Channels)
    {
        <div class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
             @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name"># @channel.Name</div>
            <div class="channel-description">@TruncateDescription(channel.Description)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<int> OnChannelSelected { get; set; }

    private string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }
}

@using sv_a01ee9c89bf24e01956feae10293996b.Services

<div class="message-item" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <div class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </div>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">Reply</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker">React</button>
        </div>

        @if (showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in commonEmojis)
                {
                    <span class="emoji-option" @onclick="() => SelectEmoji(emoji)">@emoji</span>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Message Message { get; set; } = default!;

    [Parameter]
    public int ReplyCount { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<string> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ToggleEmojiPicker()
    {
        showEmojiPicker = !showEmojiPicker;
    }

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@using sv_a01ee9c89bf24e01956feae10293996b.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h2># @Channel.Name</h2>
            <p>@Channel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="OnOpenThread"
                             OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <div class="message-input-area">
            <textarea @bind="newMessageContent" @bind:event="oninput"
                      placeholder="Type a message..."
                      @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageContent)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start messaging</p>
        </div>
    }
</div>

@code {
    [Parameter]
    public Channel? Channel { get; set; }

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private string newMessageContent = string.Empty;

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.GetValueOrDefault(messageId, 0);
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageContent)) return;
        var content = newMessageContent;
        newMessageContent = string.Empty;
        await OnSendMessage.InvokeAsync(content);
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is handled via JS interop in the page component
        await OnLoadMore.InvokeAsync();
    }
}

@using sv_a01ee9c89bf24e01956feae10293996b.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply-item">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <div class="thread-input-area">
            <textarea @bind="replyContent" @bind:event="oninput"
                      placeholder="Reply in thread..."
                      @onkeydown="HandleKeyDown"></textarea>
            <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(replyContent)">
                Reply
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Message? RootMessage { get; set; }

    [Parameter, EditorRequired]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnReply { get; set; }

    private string replyContent = string.Empty;

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(replyContent)) return;
        var content = replyContent;
        replyContent = string.Empty;
        await OnReply.InvokeAsync(content);
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendReply();
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

