{"file_text": "@page "/chat"
@using sv_a01ee9c89bf24e01956feae10293996b.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     ActiveChannelId="selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "" : "chat-main-full")">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Channel? selectedChannel;
    private int selectedChannelId;
    private Message? threadRootMessage;
    private bool isThreadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channelId);
        UpdateThreadReplyCounts();
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || selectedChannel is null) return;
        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (olderMessages.Count > 0)
        {
            messages.InsertRange(0, olderMessages);
            messageSkip += olderMessages.Count;
            UpdateThreadReplyCounts();
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        // Update reply count
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh the message to show updated reactions
        var updatedMessages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messageSkip);
        messages = updatedMessages;
    }

    private void UpdateThreadReplyCounts()
    {
        // Count replies by looking at messages with ReplyToId set
        threadReplyCounts = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}
